{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-03",
  "sketch": {
    "components": ["Nurse tablet app", "Local SQLite cache", "Sync client", "Sync API", "Patient notes service"],
    "dataStores": ["Local SQLite database on tablet", "Server-side patient notes store"],
    "externalServices": [],
    "trustBoundaries": ["Shared tablet device to backend sync API", "Nurse user to shared device", "App process to local SQLite file"],
    "dataClasses": ["health", "pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Next shift reads patient notes cached by the previous nurse",
      "scenario": "Tablets are handed over between shifts while the local SQLite cache still holds notes and medical history pulled for the previous nurse's patients. A nurse (or anyone who picks up the device in a ward) opens the app after handover and browses health records for patients they have no care relationship with. No per-user cache scoping or wipe-on-handover is described, so the exposure is silent and continuous.",
      "component": "Local SQLite cache on shared tablet",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Nurses use a tablet app that caches patient notes and medical history offline in a local SQLite database so they can work without signal. Devices are shared between shifts." }
      ],
      "cwe": ["CWE-359", "CWE-1230"],
      "plainLanguage": "The tablet keeps the last nurse's patient notes, so whoever uses it next can read them.",
      "requirement": {
        "title": "Scope and clear the offline cache per user session",
        "given": "a shared tablet holds an offline cache of patient notes from a previous nurse's session",
        "when": "that session ends, the user logs out, or a different nurse signs in",
        "then": "the cached notes and medical history for the previous user are deleted or cryptographically inaccessible before any data is shown to the new user"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Lost or stolen tablet exposes the offline health record database",
      "scenario": "Tablets are mobile and shared, so one leaving the ward in a bag or being stolen is realistic. An attacker with the device pulls the SQLite file over USB, from a backup, or after rooting it, and reads notes and medical history for every cached patient without ever touching the app login. No encryption of the local database is described.",
      "component": "Local SQLite database file",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "caches patient notes and medical history offline in a local SQLite database so they can work without signal" }
      ],
      "cwe": ["CWE-312", "CWE-311"],
      "plainLanguage": "If a tablet is lost, someone can copy the notes file off it and read the patient records.",
      "requirement": {
        "title": "Encrypt the offline patient notes database at rest",
        "given": "patient notes and medical history are stored in a local SQLite database on a tablet",
        "when": "the database file is read outside the app, for example over USB, from a device backup, or on a rooted device",
        "then": "the contents are unreadable without a key bound to device hardware and unlocked only by an authenticated nurse session"
      }
    },
    {
      "stride": "Spoofing",
      "title": "No login on a shared device lets anyone act as a nurse",
      "scenario": "The design describes a shared tablet app with no authentication step before patient data is reached. Anyone who gets physical access on the ward, including a visitor or contractor, opens the app and reads or writes patient notes as if they were the on-shift nurse, and those writes later sync to the server as legitimate clinical records.",
      "component": "Nurse tablet app sign-in",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Nurses use a tablet app that caches patient notes and medical history offline in a local SQLite database so they can work without signal. Devices are shared between shifts." },
        { "quote": "\"auth\":false" }
      ],
      "cwe": ["CWE-287", "CWE-306"],
      "plainLanguage": "Nothing proves who is holding the tablet, so anyone who picks it up can read and write patient notes.",
      "requirement": {
        "title": "Authenticate the individual nurse on every device use",
        "given": "a tablet shared between shifts",
        "when": "a user opens the app or resumes it after inactivity",
        "then": "an individual nurse credential is required before any cached or remote patient data is decrypted or displayed"
      }
    },
    {
      "stride": "Tampering",
      "title": "Edited SQLite rows sync upstream as trusted clinical records",
      "scenario": "The local SQLite database is writable on the device. Someone with file access edits or deletes note rows directly, bypassing the app, and the sync client pushes those rows to the backend. If the server trusts whatever the offline client sends, falsified medical history or removed notes become the record of care, which can change treatment decisions.",
      "component": "Sync client to Sync API",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "caches patient notes and medical history offline in a local SQLite database so they can work without signal" }
      ],
      "cwe": ["CWE-602", "CWE-345"],
      "plainLanguage": "Someone could change the notes file on the tablet and the change would be saved to the real patient record.",
      "requirement": {
        "title": "Validate and authorize every synced note server-side",
        "given": "an offline client uploads queued patient note changes",
        "when": "the sync API receives a record with a patient id, author, or timestamp",
        "then": "the server re-validates the schema and value ranges, ignores client-supplied author identity, and rejects changes for patients the authenticated nurse is not authorized to edit"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Offline cache pulls patient records beyond the nurse's assignment",
      "scenario": "To work without signal the app must pre-fetch records, and no scoping rule is stated. A nurse (or anyone using the shared tablet) can request or receive the full notes and medical history set, or change a patient identifier in the cached data or sync request, and obtain records for wards and patients outside their care assignment.",
      "component": "Pre-fetch and sync API",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "caches patient notes and medical history offline in a local SQLite database so they can work without signal" }
      ],
      "cwe": ["CWE-639", "CWE-863"],
      "plainLanguage": "The tablet may download more patients than the nurse is allowed to see.",
      "requirement": {
        "title": "Limit pre-fetch to the authenticated nurse's assigned patients",
        "given": "a nurse device requests records for offline use",
        "when": "the server builds the pre-fetch set or answers a sync pull for a patient id",
        "then": "only patients currently assigned to that authenticated nurse are returned, and requests for other patient ids are denied and recorded"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Shared devices make note authorship unprovable",
      "scenario": "Because devices are shared between shifts and no per-user identity is described, a note created or changed offline can only be attributed to the tablet, not to a person. A nurse can deny writing a harmful or incorrect note, and the organisation cannot resolve a clinical dispute or detect misuse of the record.",
      "component": "Offline note authorship and sync metadata",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Devices are shared between shifts." }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "Because the tablet is shared, you cannot tell which nurse wrote or changed a note.",
      "requirement": {
        "title": "Bind offline note changes to an individual nurse identity",
        "given": "a note is created or edited while the tablet is offline",
        "when": "the change is queued and later synced",
        "then": "it carries the authenticated nurse identity established at edit time and a server-assigned receipt time, and the server rejects changes with no authenticated author"
      }
    }
  ]
}
